mapper.select:
SELECT t.tourId, t.title, t.destination, t.description, t.price, (SELECT i.imageUrl FROM images i WHERE i.tourId = t.tourId AND i.isPrimary = TRUE LIMIT 1) as primaryImageUrl FROM tours t
AND t.tourId = #{tourId}
AND t.catalogueId = #{catalogueId}
AND t.title LIKE CONCAT('%', #{title}, '%')
AND t.destination LIKE CONCAT('%', #{destination}, '%')
AND t.price >= #{minPrice}
AND t.price <= #{maxPrice}
ORDER BY t.updateTime
